def count_sequences(n: int, last: int, memo: dict) -> int:
    if n in memo:
        return memo[n]
    if n == last:
        return 1
    total = 0
    for i in range(1, last // 2 + 1):
        total += count_sequences(n, i, memo)
    memo[n] = total
    return total

def count_sequences(n: int, last: int, memo: dict) -> int:
    # Base case: If the current sequence is empty, return 1
    if n == 1:
        return 1

    # If the current sequence has already been calculated, return the memoized result
    if last in memo:
        return memo[last]

    # Recursive case: Calculate the number of valid sequences for the current sequence
    valid_sequences = 0
    for i in range(1, last):
        if i <= last // 2:
            valid_sequences += count_sequences(n + 1, i, memo)

    # Memoize the result and return it
    memo[last] = valid_sequences
    return valid_sequences

