def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
        num (int): The integer to check for primality.

    Returns:
        bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num in [2, 3]:
        return True
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_numbers(n, rules):
    """
    Generate all unique numbers from the given number by applying transformation rules.

    Args:
        n: The original integer number to transform.
        rules: A list of transformation rules, where each rule is represented
               as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
        The total count of unique numbers that can be generated.
    """
    queue = [n]
    visited = set()
    while queue:
        num = queue.pop(0)
        if num not in visited:
            visited.add(num)
            for rule in rules:
                new_num = _transform_num(num, rule)
                if new_num not in visited:
                    queue.append(new_num)
    return len(visited)

def _transform_num(num, rule):
    x, y = rule
    new_num = str(num).replace(str(x), str(y))
    return int(new_num)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    :param scenario: The name of the participant being tested as the potential criminal.
    :param liar_count: A set of names of participants who are assumed to be liars.
    :param statements: A dictionary mapping participant names to lists of their respective statements.
    :param days_of_week: A set of strings representing the days of the week.
    :return: True if the scenario is consistent with the statements, False otherwise.
    """
    # Check if the scenario is consistent with the statements
    for statement in statements[scenario]:
        if statement not in days_of_week:
            return False
    # Check if the other participants are consistent with the scenario
    for participant, statement_list in statements.items():
        if participant == scenario:
            continue
        if participant in liar_count and statement_list[0] not in days_of_week:
            return False
    return True

