def calculate_score(system: int, points: str) -> list:
    scores = []
    player_score = 0
    opponent_score = 0
    for point in points:
        if point == 'W':
            player_score += 1
        else:
            opponent_score += 1
        if player_score == system or opponent_score == system:
            scores.append(f'{player_score}:{opponent_score}')
            player_score = 0
            opponent_score = 0
    if player_score > opponent_score and player_score >= system - 2:
        scores.append(f'{player_score}:{opponent_score}')
    elif opponent_score > player_score and opponent_score >= system - 2:
        scores.append(f'{player_score}:{opponent_score}')
    return scores

def catalan_number(n: int) -> int:
    """
    Calculate the nth Catalan number.

    Args:
        n (int): The position in the Catalan number sequence to compute (must be non-negative).

    Returns:
        int: The nth Catalan number.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 1
    return sum(catalan_number(i) * catalan_number(n-1-i) for i in range(n))

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        for j in range(V + 1):
            if j < volumes[i - 1]:
                dp[i] = max(dp[i], dp[i - 1])
            else:
                dp[i] = max(dp[i], dp[i - 1] + volumes[i - 1])
    return V - dp[n]

